import { ITEMS_TAG } from '@/lib/posts';

/* DROP THE CACHED FEED THE MOMENT A ROW CHANGES (2026-09-15).
 *
 * Every surface reads the items table through one unstable_cache entry on an hourly window, and
 * that window is a deliberate cost decision (see the note in src/lib/posts.ts). What it cannot do
 * is answer a write: scripts/mirror-posts.mjs runs after every posting tick, and a plain GET
 * inside the window is answered from the CDN, so the row it just wrote stays invisible while the
 * log says the pages were warmed. This is the request that actually invalidates.
 *
 * Guarded by the estate shared REVALIDATE_SECRET header, the same shape fetchdue uses, so nothing
 * public can spend a regeneration.
 */
export async function POST(req: NextRequest) {
  const secret = process.env.REVALIDATE_SECRET;
  if (!secret || req.headers.get('x-revalidate-secret') !== secret) {
    return NextResponse.json({ ok: false }, { status: 401 });
  }
  revalidateTag(ITEMS_TAG);
  const paths = ['/', '/wire', '/search', '/sources', '/sitemap.xml'];
  for (const p of paths) revalidatePath(p);
  return NextResponse.json({ ok: true, tag: ITEMS_TAG, revalidated: paths });
}
